// Guarda de saída (v2.12) — última peça antes do WhatsApp, e a única que não depende do modelo.
// 1) apaga link que não seja do próprio Moedin.IA: nem o modelo nem um PDF malicioso conseguem usar
//    o bot para mandar phishing ou vazar dado numa querystring (o usuário confia no bot);
// 2) tira as marcas internas [[CONTEUDO-LIDO:...]], que nunca devem aparecer para o usuário;
// 3) corta resposta gigante (WhatsApp corta em ~4096).
const PERMITIDOS = ['moedin-ia.com.br', 'moedin-ia.vercel.app', 'wa.me'];
const doEnv = (String($env.MOEDIN_APP_URL || '').match(/^https?:\/\/([^\/]+)/) || [])[1];
if (doEnv) PERMITIDOS.push(doEnv.replace(/^www\./i, '').toLowerCase());
let t = String($json.output || '').replace(/\[\[\/?CONTEUDO-LIDO:[^\]]*\]\]/g, '').trim();
let removidos = 0;
t = t.replace(/\bhttps?:\/\/[^\s<>()\[\]]+|\bwww\.[^\s<>()\[\]]+/gi, (u) => {
  const host = u.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[\/?#]/)[0].toLowerCase();
  if (PERMITIDOS.some(d => host === d || host.endsWith('.' + d))) return u;
  removidos++;
  return '(link removido por segurança)';
});
if (t.length > 3500) t = t.slice(0, 3500).trim() + '…';
return [{ json: { output: t || 'Não consegui montar uma resposta agora. Pode repetir? 🙏', links_removidos: removidos } }];
